result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/test_clustering_benchmark.py", "content": "import json
import os

import pyarrow.parquet as pq
import pytest

HERE = os.path.dirname(os.path.abspath(__file__))
N_ROWS = 300_000


@pytest.fixture(scope="session")
def report() -> dict:
    assert os.path.isfile(os.path.join(HERE, "comparison.json")), (
        "run generate_data.py and stats_compare.py first"
    )
    with open(os.path.join(HERE, "comparison.json")) as f:
        return json.load(f)


def _lake_files(lake: str) -> list[str]:
    paths = sorted(
        os.path.join(HERE, lake, p)
        for p in os.listdir(os.path.join(HERE, lake))
        if p.endswith(".parquet")
    )
    assert len(paths) == 6, f"{lake} should have 6 files"
    return paths


def test_row_group_size_is_25000():
    for lake in ("unclustered", "clustered"):
        for path in _lake_files(lake):
            md = pq.ParquetFile(path).metadata
            for rg in range(md.num_row_groups):
                assert md.row_group(rg).num_rows <= 25_000


def test_clustered_touches_at_most_one_file(report):
    assert report["clustered"]["files"] >= 1
    assert report["clustered"]["files"] <= 1


def test_unclustered_touches_all_six_files(report):
    assert report["unclustered"]["n_files"] == 6
    assert report["unclustered"]["files"] == 6


def test_matching_row_counts_equal(report):
    u = report["unclustered"]["matching_rows"]
    c = report["clustered"]["matching_rows"]
    assert u == c
    assert u > 0
    assert report["matching_rows_equal"] is True


@pytest.mark.parametrize("lake", ["unclustered", "clustered"])
def test_total_rows_300k(lake):
    total = sum(pq.ParquetFile(p).metadata.num_rows for p in _lake_files(lake))
    assert total == N_ROWS


def test_lakes_contain_identical_rows():
    import pyarrow.compute as pc

    def sorted_digest(paths):
        tables = [pq.read_table(p) for p in paths]
        t = pa_table_concat(tables)
        idx = pc.sort_indices(t, sort_keys=[("device_id", "ascending"), ("ts", "ascending"), ("reading", "ascending")])
        return t.take(idx)

    from functools import reduce

    def pa_table_concat(ts_):
        return reduce(lambda a, b: pa.concat_tables([a, b]), ts_)

    import pyarrow as pa

    u = sorted_digest(_lake_files("unclustered"))
